<script setup>
import{computed,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{teacherApi,formatTime}from'../../api/teacher';import{lifecycleNames}from'../../utils/examLifecycle';import TeacherModal from'../../components/TeacherModal.vue';import ExamForm from'../../components/ExamForm.vue';import QuestionForm from'../../components/QuestionForm.vue';import QuestionBankPicker from'../../components/QuestionBankPicker.vue';import RandomPaperComposer from'../../components/RandomPaperComposer.vue';import ExamCandidatesPanel from'../../components/ExamCandidatesPanel.vue';import ExamGradingPanel from'../../components/ExamGradingPanel.vue'
const route=useRoute(),router=useRouter(),exam=ref(),workspace=ref(),questions=ref([]),error=ref(''),notice=ref(''),loading=ref(true),busy=ref(false),editExam=ref(false),editQuestion=ref(false),pickFromBank=ref(false),randomCompose=ref(false),selected=ref();const tabs=[['overview','考试概览'],['paper','试卷内容'],['candidates','考生情况'],['grading','阅卷与成绩']];const active=computed(()=>tabs.some(t=>t[0]===route.query.tab)?route.query.tab:'overview');async function load(){loading.value=true;try{const[w,e,q]=await Promise.all([teacherApi.examWorkspace(route.params.examId),teacherApi.exam(route.params.examId),teacherApi.questions(route.params.examId)]);workspace.value=w.data;exam.value=e.data;questions.value=q.data}catch(e){error.value=e.message}finally{loading.value=false}}function tab(value){router.push({path:route.path,query:{tab:value}})}function openQuestion(q){selected.value=q;editQuestion.value=true}async function saved(){editExam.value=false;editQuestion.value=false;notice.value='保存成功';await load()}async function bankQuestionsAdded(count){pickFromBank.value=false;notice.value=`已从题库加入 ${count} 道题`;await load()}async function randomPaperAdded(count){randomCompose.value=false;notice.value=`已随机加入 ${count} 道题`;await load()}async function remove(q){if(!confirm('确定删除题目“'+q.content.slice(0,40)+'”及其评分点吗？'))return;try{await teacherApi.deleteQuestion(q.id);notice.value='题目已删除';await load()}catch(e){error.value=e.message}}async function publish(){if(!confirm('考试发布后关键规则和题目将受到限制，确定发布吗？'))return;busy.value=true;try{await teacherApi.publish(exam.value.id);notice.value='考试发布成功';await load()}catch(e){error.value=e.message}finally{busy.value=false}}watch(()=>route.params.examId,()=>{consumeWorkspaceNotice();load()});function consumeWorkspaceNotice(){const tip=sessionStorage.getItem('examWorkspaceNotice:'+route.params.examId);if(tip){sessionStorage.removeItem('examWorkspaceNotice:'+route.params.examId);notice.value=tip}}onMounted(()=>{consumeWorkspaceNotice();load()})
</script>
<template><p v-if="error" class="error-message">{{error}}</p><p v-if="notice" class="success-message">{{notice}}</p><p v-if="loading" class="empty-state">正在加载考试…</p><template v-if="exam&&workspace"><RouterLink to="/teacher/exams">← 返回考试列表</RouterLink><header class="exam-workspace-heading"><div><div class="actions"><h1>{{exam.title}}</h1><span :class="['badge',workspace.lifecycleStatus]">{{lifecycleNames[workspace.lifecycleStatus]}}</span></div><p>{{exam.courseName}} · 考试时间：{{formatTime(exam.startTime)}} - {{formatTime(exam.endTime)}} · {{exam.questionCount}}题 / {{exam.totalScore}}分</p></div></header><div class="workspace-stats"><div><span>应考</span><strong>{{workspace.candidateCount}}</strong></div><div><span>答题中</span><strong>{{workspace.inProgressCount}}</strong></div><div><span>已提交</span><strong>{{workspace.submittedCount+workspace.autoSubmittedCount+workspace.reviewedCount}}</strong></div><div><span>已阅</span><strong>{{workspace.reviewedCount}}</strong></div><div class="workspace-stat-emphasis"><span>待阅</span><strong>{{workspace.pendingReviewCount}}</strong></div><div><span>缺考</span><strong>{{workspace.absentCount}}</strong></div></div><nav class="workspace-tabs" aria-label="考试工作区"><button v-for="item in tabs" :key="item[0]" :class="{active:active===item[0]}" @click="tab(item[0])">{{item[1]}}</button></nav>
<section v-if="active==='overview'" class="surface overview-grid"><div><h2>考试基本信息</h2><p class="preserve">{{exam.description||'暂无考试说明'}}</p><div class="course-meta"><span>课程：{{exam.courseName}}</span><span>开始：{{formatTime(exam.startTime)}}</span><span>结束：{{formatTime(exam.endTime)}}</span><span>迟到允许：{{exam.lateEntryMinutes}} 分钟</span><span>最早交卷：{{exam.minSubmitMinutes}} 分钟</span><span>试卷：{{exam.questionCount}} 题 / {{exam.totalScore}} 分</span></div></div><div class="next-action"><h2>下一步</h2><template v-if="workspace.lifecycleStatus==='DRAFT'"><p>完善试卷后发布考试并冻结应考名单。</p><button class="primary" @click="tab('paper')">完善试卷</button></template><template v-else-if="workspace.lifecycleStatus==='IN_PROGRESS'"><p>考试正在进行，已进入 {{workspace.inProgressCount+workspace.submittedCount+workspace.autoSubmittedCount+workspace.reviewedCount}} / {{workspace.candidateCount}}。</p><button class="primary" @click="tab('candidates')">查看考生情况</button></template><template v-else-if="['PENDING_REVIEW','REVIEWING'].includes(workspace.lifecycleStatus)"><p>还有 {{workspace.pendingReviewCount}} 份答卷待阅。</p><button class="primary" @click="tab('grading')">继续阅卷</button></template><template v-else-if="workspace.lifecycleStatus==='READY_TO_RELEASE'"><p>全部有效答卷已完成阅卷。</p><button class="primary" @click="tab('grading')">发布本场成绩</button></template><template v-else-if="workspace.lifecycleStatus==='RESULTS_RELEASED'"><p>成绩已于 {{formatTime(workspace.resultsReleasedAt)}} 发布。</p><button class="secondary" @click="tab('grading')">查看与导出成绩</button></template><template v-else><p>考试尚未开始。</p><button class="secondary" @click="tab('candidates')">查看应考名单</button></template></div></section>
<section v-if="active==='paper'"><div class="section-head"><h2>试卷内容 <span class="muted">共 {{exam.questionCount}} 题 · 总分 {{exam.totalScore}} 分</span></h2><div v-if="exam.status==='DRAFT'" class="actions"><button class="secondary" @click="editExam=true">编辑考试</button><button class="secondary" @click="openQuestion(null)">+ 手动新增题目</button><button class="primary" @click="pickFromBank=true">从题库选题</button><button class="secondary" @click="randomCompose=true">随机组卷</button><button class="primary" :disabled="busy" @click="publish">{{busy?'发布中…':'发布考试'}}</button></div></div><p v-if="!questions.length" class="empty-state">试卷还是空的，添加一道单选题或简答题开始设计。</p><article v-for="q in questions" :key="q.id" class="surface question-card"><header class="section-head"><div class="actions"><span class="question-order">{{q.sortOrder}}</span><span :class="['badge',q.questionType]">{{q.questionType==='SINGLE_CHOICE'?'单选题':'简答题'}}</span><strong>{{q.score}} 分</strong></div><div v-if="exam.status==='DRAFT'" class="actions"><button class="ghost" @click="openQuestion(q)">编辑题目</button><button class="danger" @click="remove(q)">删除题目</button></div></header><h3 class="preserve">{{q.content}}</h3><div v-for="o in q.options" :key="o.key" class="option-row"><strong>{{o.key}}.</strong> {{o.text}}</div><div class="answer-preview preserve"><strong>{{q.questionType==='SINGLE_CHOICE'?'正确答案':'参考答案'}}：</strong>{{q.referenceAnswer}}</div><div v-if="q.questionType==='SHORT_ANSWER'"><h4>评分点</h4><ol><li v-for="p in q.scoringPoints" :key="p.id">{{p.pointContent}} <strong>{{p.pointScore}} 分</strong></li></ol></div></article></section>
<ExamCandidatesPanel v-if="active==='candidates'" :exam-id="exam.id" :draft="exam.status==='DRAFT'"/><ExamGradingPanel v-if="active==='grading'" :exam-id="exam.id" :workspace="workspace" @released="load"/>
<TeacherModal v-if="editExam" title="编辑考试" @close="editExam=false"><ExamForm :course-id="exam.courseId" :exam="exam" @saved="saved"/></TeacherModal><TeacherModal v-if="editQuestion" :title="selected?'编辑题目':'添加题目'" @close="editQuestion=false"><QuestionForm :exam-id="exam.id" :question="selected" :next-order="questions.length?Math.max(...questions.map(q=>q.sortOrder))+1:1" @saved="saved"/></TeacherModal><TeacherModal v-if="pickFromBank" title="从题库选题" @close="pickFromBank=false"><QuestionBankPicker :exam-id="exam.id" @saved="bankQuestionsAdded"/></TeacherModal><TeacherModal v-if="randomCompose" title="随机组卷" @close="randomCompose=false"><RandomPaperComposer :exam-id="exam.id" @saved="randomPaperAdded" @close="randomCompose=false"/></TeacherModal></template></template>
